import {exerciseCatalog} from './data.js';
import {comparableProgress,observeState,setup,upsertProfile,experiment} from './fitness.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={empty:'等待第一条记录',ambiguous:'同日多场，暂不自动比较',insufficient:'还需匹配记录',incomparable:'条件不足，暂不判断',mixed:'有升有降',up:'匹配组有提高',down:'匹配组有下降',flat:'匹配组保持相同'};
const setText=(s,t)=>`${t==='reps'?'自重':s.weight+' kg'} × ${s.reps} 次 · RIR ${s.rir??'未记录'}`;
export function mountFitness(root,{getData,save,space,openSession,notify}){
  const available=()=>[...new Set([...getData().sessions.flatMap(s=>s.exercises.map(e=>e.name)),...exerciseCatalog(getData().customExercises??[]).flatMap(g=>g.exercises)])];
  const saved=getData().fitnessExperiment;let name=saved?.name??available()[0]??'',tab='progress',days=90,factor=saved?.factor??'sleepHours',threshold=saved?.threshold??7,question=saved?.question??'',error='';
  function links(entries){return entries.map(e=>`<button class="view-link" data-fit="source" data-id="${esc(e.id)}">${esc(e.date)} · ${esc(e.title)}</button>`).join('');}
  function progress(){const p=comparableProgress(getData().sessions,name,{days});return `<section class="panel fitness-verdict"><span class="chip">${labels[p.status]}</span><h2>比较相近条件，才看得更清楚。</h2><p class="sub">匹配已记录的动作顺序、器械设置、工作组序和相同 RIR；同重量比次数，同次数比重量。</p>${p.latest&&!p.latest.setupKnown?'<p class="notice">器械名称未记录，不能确认是否同一器械；下面仅比较其余已记录条件。</p>':''}${p.latest?`<p class="fitness-dates">${p.baseline?esc(p.baseline.date)+' → ':''}${esc(p.latest.date)}</p>`:''}${p.reason?`<div class="notice">${esc(p.reason)}</div>`:''}${p.pairs.length?`<div class="fitness-pairs">${p.pairs.map(pair=>`<article><span>第 ${pair.ordinal} 工作组</span><strong class="${pair.delta>0?'fitness-up':''}">${pair.delta>0?'+':''}${pair.delta} ${pair.metric==='weight'?'kg':'次'}</strong><p>${setText(pair.before,p.latest.tracking)}<br>→ ${setText(pair.after,p.latest.tracking)}</p></article>`).join('')}</div><p class="sub">${p.pairs.length} 组匹配 · ${p.unmatched} 组条件不同或信息不足。${p.skippedRecent?`跳过 ${p.skippedRecent} 场较近但设置不同的记录。`:''}这只描述匹配组，不代表整场训练或增肌效果。</p>`:''}<details class="fitness-method"><summary>比较条件与限制</summary><p>以最近有效日期为当前记录，以更早、设置一致的最近记录为基线。不会挑历史最弱的一次来制造进步；组序按已完成工作组排列，不匹配热身。RIR 是主观记录。</p><p>${p.latest?.setupKnown?'已记录器械名称；仍依赖你使用一致的名称和设置。':'器械名称未记录，无法核对是否同一器械。'}未控制动作幅度、节奏、体重与真实休息时间。自重次数变化也不等于力量变化。</p><p>旧记录没有设置时，仅与同样未记录设置的条目比较，仍显示信息缺口。新设置不会回填旧训练。</p></details></section><section class="panel"><div class="section-head"><h2>回到来源记录</h2><span class="muted">${p.entries.length} 条有效记录</span></div><div class="fitness-sources">${links(p.baseline?[p.latest,p.baseline]:p.latest?[p.latest]:[])||'<p class="sub">保存训练后可查看来源。</p>'}</div></section>`;}
  function profiles(){const profile=getData().fitnessProfiles?.find(p=>p.name===name),v=setup(profile?.setup??{}),usable=exerciseCatalog(getData().customExercises??[]).some(g=>g.exercises.includes(name));return `<section class="panel"><div class="section-head"><h2>让器械设置跟着动作走</h2><span class="chip">下次加入时带入</span></div><p class="sub">设置保存在本机。每次新加动作会保存一份当次快照；以后修改器械卡，不会改写历史。</p><form data-fitness-form="profile" class="fitness-form"><label>器械 / 场地标识<input name="equipment" maxlength="60" placeholder="例如：二楼悍马卧推 A" value="${esc(v.equipment)}"></label><div class="fitness-field-grid"><label>座椅 / 档位<input name="seat" maxlength="40" placeholder="例如：座椅第 3 档" value="${esc(v.seat)}"></label><label>握法 / 其他设置<input name="grip" maxlength="40" placeholder="例如：窄握，手柄 B" value="${esc(v.grip)}"></label></div><label>每组休息计时 / 秒<input name="restSeconds" type="number" inputmode="numeric" min="15" max="600" step="1" required value="${v.restSeconds}"></label><p class="sub">这是你自己的计时偏好，不是系统给出的训练处方。可在本次训练中单独修改。</p><button class="primary" ${usable?'':'disabled'}>保存器械卡</button>${usable?'':'<p class="sub">该动作已不在可选库中，请先恢复动作。</p>'}</form></section><section class="panel"><h2>器械被占用？临时换一个。</h2><p class="sub">在训练编辑器展开「本次设置与替换」，自行挑选同部位的另一个动作。替换只允许在原动作没有完成组时进行，也不会复制原动作的重量和次数。同部位不代表效果相同。</p></section>`;}
  function observation(){const p=observeState(getData().sessions,name,{days,factor,threshold}),unit=factor==='sleepHours'?'小时':'级',factorName=factor==='sleepHours'?'睡眠时长':'训练前疲劳感';return `<section class="panel"><span class="chip">个人观察 · 本机分析</span><h2>这次想观察什么？</h2><form data-fitness-form="experiment" class="fitness-form"><label>观察问题（可选）<textarea name="question" maxlength="200" rows="2" placeholder="例如：睡眠记录不同时，我的首组次数是否也不同？">${esc(question)}</textarea></label><div class="fitness-field-grid"><label>记录因素<select id="fitness-factor"><option value="sleepHours" ${factor==='sleepHours'?'selected':''}>前一晚睡眠时长</option><option value="fatigue" ${factor==='fatigue'?'selected':''}>训练前疲劳感 1–5</option></select></label><label>分组界线 / ${unit}<input id="fitness-threshold" type="number" min="${factor==='sleepHours'?.5:1}" max="${factor==='sleepHours'?23.5:4}" step="${factor==='sleepHours'?.5:1}" value="${threshold}" required></label></div><p class="sub">这是自选分组界线，不是睡眠或恢复的健康标准。下方只观察同设置、同动作顺序、同重量与 RIR 的首个工作组次数。</p><button class="secondary">保存观察主题</button></form></section><section class="panel fitness-observation"><div class="section-head"><h2>${factorName}与首组表现</h2><span class="chip">${p.status==='ready'?'达到展示样本门槛':'样本不足'}</span></div><div class="fitness-observation-grid">${p.groups.map((g,i)=>`<article><span>${i?'大于或等于':'小于'} ${threshold} ${unit}</span><strong>${g.length}<small> 个日期</small></strong><p>${g.length?'平均首组 '+p.means[i]+' 次':'暂无匹配样本'}</p></article>`).join('')}</div>${p.status==='ready'?`<p class="fitness-dates">右组比左组平均 ${p.difference>0?'多':p.difference<0?'少':'相同，差值为'} ${Math.abs(p.difference)} 次</p>`:''}<p class="sub">${esc(p.reason)} ${p.excluded??0} 条记录因缺少状态、条件不同或同日重复而未纳入。</p>${p.anchor?`<p class="sub">参照：${esc(p.anchor.date)} · 第 ${p.anchor.position+1} 个动作 · ${setText(p.anchor.sets[0],p.anchor.tracking)}。${p.anchor.setupKnown?'器械设置已记录。':'器械设置未记录，观察局限更大。'}</p>`:''}<details class="fitness-method"><summary>查看样本与观察边界</summary><p>每侧至少 3 个不同日期才展示均值差。这是产品展示门槛，不表示统计显著或科学验证。样本量不均衡、选择性记录、动作质量等因素都可能影响结果；不会建议你主动少睡来测试。</p><div class="fitness-sources">${links(p.groups.flat())||'还没有匹配样本。'}</div></details></section>`;}
  function draw(){root.innerHTML=`<div class="page-heading"><div><h1>进步，需要一点证据。</h1><p class="sub">看表现、记设置，再观察自己的训练规律。</p></div><span class="review-pill">${space==='demo'?'示例数据 · 非真实效果':'仅在本机分析'}</span></div><nav class="fitness-tabs" aria-label="训练洞察功能">${[['progress','表现对比'],['profiles','器械卡'],['observation','状态观察']].map(([key,label])=>`<button data-fit="tab" data-tab="${key}" class="${tab===key?'active':''}" aria-pressed="${tab===key}">${label}</button>`).join('')}</nav><div class="panel fitness-controls"><label>选择动作<select id="fitness-name">${available().map(n=>`<option ${n===name?'selected':''}>${esc(n)}</option>`).join('')}</select></label>${tab==='profiles'?'':`<label>查看周期<select id="fitness-days"><option value="28" ${days===28?'selected':''}>近 28 天</option><option value="90" ${days===90?'selected':''}>近 90 天</option></select></label>`}</div>${error?`<p class="notice" role="status">${esc(error)}</p>`:''}<div class="fitness-panels">${tab==='progress'?progress():tab==='profiles'?profiles():observation()}</div>`;}
  root.onclick=e=>{const b=e.target.closest('[data-fit]');if(!b)return;if(b.dataset.fit==='tab'){const q=root.querySelector('[name="question"]');if(q)question=q.value;tab=b.dataset.tab;error='';draw();}if(b.dataset.fit==='source')openSession(b.dataset.id);};
  root.onchange=e=>{const t=e.target;if(t.id==='fitness-name')name=t.value;else if(t.id==='fitness-days')days=Number(t.value);else if(t.id==='fitness-factor'){question=root.querySelector('[name="question"]')?.value??question;factor=t.value;threshold=factor==='sleepHours'?7:3;}else if(t.id==='fitness-threshold'){question=root.querySelector('[name="question"]')?.value??question;const v=Number(t.value);if(!t.checkValidity()||!t.value){error='请填写范围内的有效分组界线。';return;}threshold=v;}else return;error='';draw();};
  root.onsubmit=e=>{const form=e.target.closest('[data-fitness-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const data=getData();try{if(form.dataset.fitnessForm==='profile'){const fields=Object.fromEntries(new FormData(form)),previous=data.fitnessProfiles;data.fitnessProfiles=upsertProfile(data,name,fields).fitnessProfiles;if(!save()){data.fitnessProfiles=previous;return;}notify('器械卡已保存，只影响以后新加入的动作。');}else{question=form.querySelector('[name="question"]').value;const previous=data.fitnessExperiment;data.fitnessExperiment=experiment({name,factor,threshold,question});if(!save()){data.fitnessExperiment=previous;return;}notify('观察主题已保存，新增记录后会重新核对。');}error='';draw();}catch(err){error=err.message;draw();}};
  draw();
}
